questionvariables.text:
stack_include("https://raw.githubusercontent.com/STACK-for-Chemistry/STACK-for-Chemistry/refs/heads/main/Modules/Utilized/pse.mac");
      stack_include("https://raw.githubusercontent.com/STACK-for-Chemistry/STACK-for-Chemistry/refs/heads/main/Modules/Utilized/electrochemistry.mac");
      stack_unit_si_declare(true);

      /* Alle Datenbankeinträge der Form M^n+ + n e^- -> M.
         Die lokale Filterung verwendet die bereits veröffentlichte API des
         importierten Elektrochemie-Moduls. */
      metal_reductants: ["Ag", "Al", "Au", "Ba", "Ca", "Cd", "Co", "Cu", "Fe", "Hg", "K", "Li", "Mg", "Mn", "Na", "Ni", "Pb", "Sn", "Zn"];
      all_pairs: chem_electrochem_pairs_array();
      metal_pairs: [];
      pair_index: 1;
      while pair_index <= length(all_pairs) do (
        current_pair: all_pairs[pair_index],
        if member(second(current_pair), metal_reductants) then
          metal_pairs: endcons([
            first(current_pair),
            second(current_pair),
            chem_electrochem_n(first(current_pair), second(current_pair)),
            chem_electrochem_E0(first(current_pair), second(current_pair))
          ], metal_pairs),
        pair_index: pair_index + 1
      );

    /* Zwei unterschiedliche Metalle auswählen; die Richtung wird erst danach über E0 festgelegt. */
    pair_one: rand(metal_pairs);
    pair_two: rand(metal_pairs);
    while sequal(second(pair_one), second(pair_two)) or is(third(pair_one) = third(pair_two)) do pair_two: rand(metal_pairs);

    if is(fourth(pair_one) > fourth(pair_two)) then (
      cathode_pair: pair_one,
      anode_pair: pair_two
    ) else (
      cathode_pair: pair_two,
      anode_pair: pair_one
    );

    cathode_ion: first(cathode_pair);
    cathode_metal: second(cathode_pair);
    n_cathode: third(cathode_pair);
    E_cathode: fourth(cathode_pair);
    anode_ion: first(anode_pair);
    anode_metal: second(anode_pair);
    n_anode: third(anode_pair);
    E_anode: fourth(anode_pair);

    g: gcd(n_cathode, n_anode);
    coefficient_cathode: n_anode/g;
    coefficient_anode: n_cathode/g;
    z: n_cathode*n_anode/g;
    coefficient_text(x) := if is(x = 1) then "" else string(x);
    term(x, species) := sconcat(coefficient_text(x), species);

    cathode_ion_aq: sconcat(cathode_ion, "(aq)");
    anode_ion_aq: sconcat(anode_ion, "(aq)");
    cathode_ion_display: chem_display(cathode_ion);
    anode_ion_display: chem_display(anode_ion);
    cathode_ion_aq_display: chem_display(cathode_ion_aq);
    anode_ion_aq_display: chem_display(anode_ion_aq);
    cathode_metal_display: chem_display(sconcat(cathode_metal, "(s)"));
    anode_metal_display: chem_display(sconcat(anode_metal, "(s)"));
    cathode_half_equation: chem_display(sconcat(cathode_ion_aq, " + ", string(n_cathode), "e^- -> ", cathode_metal, "(s)"));
    anode_half_equation: chem_display(sconcat(anode_ion_aq, " + ", string(n_anode), "e^- -> ", anode_metal, "(s)"));
    overall_reaction: sconcat("\\ce{", term(coefficient_anode, sconcat(anode_metal, "(s)")), " + ", term(coefficient_cathode, cathode_ion_aq), " -> ", term(coefficient_anode, anode_ion_aq), " + ", term(coefficient_cathode, sconcat(cathode_metal, "(s)")), "}");

    E_standard: float(E_cathode - E_anode);

T: 298.15;
R: 8.314;
F: 96485;
c_anode: rand([0.5, 1.0]);
c_cathode: rand([0.5, 1.0]);
Q_reaction: float(c_anode^coefficient_anode/c_cathode^coefficient_cathode);
E_nernst_raw: E_standard - R*T/(z*F)*log(Q_reaction);
E_nernst: float(round(100*E_nernst_raw)/100);

ta_standard: stackunits(E_standard, V);
ta_nernst: stackunits(E_nernst, V);
